function chapterToDifficulty(ch: IrodoriChapterNumber): DifficultyLevel {
  if (ch <= 6) return 'easy';
  if (ch <= 12) return 'medium';
  return 'hard';
}

export const IRODORI_DATA: KanjiEntry[] = RAW_IRODORI.map(
  ([chapter, k, r, accent, m, subSection, ex, exi], idx) => ({
    id: `ir${idx + 1}`,
    k,
    r,
    m,
    ex,
    exi,
    lv: 'N4',
    dif: chapterToDifficulty(chapter),
    chapter,
    accent,
    subSection,
  })
);

export const VALID_IRODORI_IDS: Set<string> = new Set(IRODORI_DATA.map(it => it.id));

export function getIrodoriPoolIndices(
  chapterFilter: IrodoriChapterFilter,
  dataset: readonly KanjiEntry[] = IRODORI_DATA
): number[] {
  const out: number[] = [];
  for (let i = 0; i < dataset.length; i++) {
    if (chapterFilter === 'all' || dataset[i].chapter === chapterFilter) {
      out.push(i);
    }
  }
  return out;
}
